# PPSDK2.4 API

## 注意
需要把app.js放在项目assets目录下，这样确保Application脚本能第一时间被执行
```ts
/**@description 根据引用顺序 app.js会优先执行 为了Application能够优先被执行 */
require('./resources/PPSDK/framework/Application');
```

## 初始化
`PPSDK.init()` 为PPSDK初始化函数
```ts
    //初始化
    PPSDK.init({
        language: language,                 //语言
        onCompleted: () => {                //初始化完成函数
            Log.d('PPSDK 初始化完成');
        }
    })
```

## 框架配置
在`PPSDK/config/PPSDK_Config`,主要是一些项目配置,根据需求进行配置
```ts
export namespace Config {
    /**@description 公共音效路径 */
    export const audioPath = {
        button: "common/audios/btn_click",           //按钮点击音效
    }
    /**@description 是否使用按钮音效，即cc.Button默认会播放音效   */
    export const USE_BUTTON_SFX = true;

    /**@description Loading动画显示超时回调默认超时时间 */
    export const LOADING_TIME_OUT = 30;

    /**@description 弹出Loading时，在延迟delay后再显示Loading界面 */
    export const LOADING_DELAY = 0.1;

    /**@description Loading提示中切换显示内容的时间间隔 */
    export const LOADING_CONTENT_CHANGE_INTERVAL = 3;

    /**@description 加载界面超时时间,如果在LOAD_VIEW_TIME_OUT秒未加载出，提示玩家加载界面超时 */
    export const LOAD_VIEW_TIME_OUT = 20;

    /**@description UILoading显示默认时间，即在打开界面时，如果界面在LOAD_VIEW_DELAY之内未显示，就会弹出一的加载界面的进度 
     * 在打开界面时，也可直接指定delay的值
     */
    export const LOAD_VIEW_DELAY = 0.1;

    /**@description 是否使用内置提示组件*/
    export const USE_SYS_TIPS = true;
    export const USE_SYS_ALERT = true;
    export const USE_SYS_LOADING = true;
    export const USE_SYS_UILOADING = true;
}

//语言配置
export namespace LanguageConfig {
    /**@description 是否允许游戏启动后切换语言 */
    export const ENABLE_CHANGE_LANGUAGE = true;

    /**@description 通用路径 */
    export const GENERAL_LANGUAGE_SPRITE_ROOT = "language/sprite";
    export const GENERAL_LANGUAGE_LABEL_ROOT = "language/label"
}

```


## 公共UI组件
### toast 提示语
默认为系统toast,如果要置换为自定义toast,可调用`PPSDK.tips.setPrefab()`方法，自定义toast挂载脚本需扩展`TipsClass`
```ts
    PPSDK.showToast("msg");
```

### loading 加载
默认为系统loading,如果要置换为自定义loading,可调用`PPSDK.loading.setPrefab()`方法，自定义loading挂载脚本需扩展`LoadingClass`
```ts
    //显示loading
    PPSDK.showLoading({
        msg: "加载中",                      //显示信息
        timeout: 5,                         //超时限制，不设置则不限制
        timeoutCb: () => {                  //超时回调
            PPSDK.showToast('加载超时');
        }
    })
    //隐藏loading
    PPSDK.hideLoading();
    
```

### alert 提示框
默认为系统alert,如果要置换为自定义alert,可调用`PPSDK.alert.setPrefab()`方法，自定义alert挂载脚本需扩展`AlertClass`
```ts
    PPSDK.showAlert({
        title: "Test",
        content: "Test content",
        showCancel: true,
        confirm: () => {
            Log.d('alert confirm');
        },
        cancel: () => {
            Log.d('alert cancel');
        }
    })
```

## 音乐音效震动
```ts
    //获得设置音乐状态(get,set)
    PPSDK.musicState
    //获得设置音效状态(get,set)
    PPSDK.sfxState
    //获得设置震动状态(get,set)
    PPSDK.vibrateState

    //播放音乐(bundle下路径，bundle名)
    PPSDK.playMusic('audio/bgm', 'example');
    //播放音效(bundle下路径，bundle名)
    PPSDK.playSfx('audio/sfx', 'example');
    //停止音乐
    PPSDK.stopMusic();
    //震动(是否是长震动)
    PPSDK.vibrate(false);
```

## 事件系统
